import{_ as d,o as e,c as o,a5 as a}from"./chunks/framework.BYIUCCsM.js";const b=JSON.parse('{"title":"架构总览","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md","lastUpdated":1788129119000}'),n={name:"overview.md"};function s(c,t,r,i,p,l){return e(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h1><p>XiHan.UI 是一个 pnpm + turbo 的 monorepo。它的组织方式只服务于一件事：<strong>让「组件的行为」独立于「渲染它的框架」存在</strong>。</p><h2 id="一个组件的四份产物" tabindex="-1">一个组件的四份产物 <a class="header-anchor" href="#一个组件的四份产物" aria-label="Permalink to &quot;一个组件的四份产物&quot;">​</a></h2><p>以对话框为例，<code>dialog</code> 这个组件在仓库里落成四处：</p><table tabindex="0"><thead><tr><th>产物</th><th>位置</th><th>内容</th></tr></thead><tbody><tr><td>无头内核</td><td><code>packages/engine/headless/src/dialog/</code></td><td>解剖、状态机、键盘规格表、<code>connect</code></td></tr><tr><td>Vue 组件</td><td><code>packages/adapters/vue/src/components/dialog/</code></td><td><code>XhDialogRoot</code> 等一组 <code>defineComponent</code></td></tr><tr><td>自定义元素</td><td><code>packages/adapters/web-components/src/elements/dialog.ts</code></td><td><code>&lt;xh-dialog&gt;</code>，Light-DOM 行为宿主</td></tr><tr><td>皮肤</td><td><code>packages/design/styles/css/dialog.css</code></td><td>纯 CSS，按 <code>data-*</code> 选中</td></tr></tbody></table><p>四份里只有第一份包含逻辑。后三份分别回答「怎么把属性挂到 Vue 的 vnode 上」「怎么把属性挂到作者手写的 DOM 上」「这些属性长什么样」。</p><h2 id="分层与依赖矩阵" tabindex="-1">分层与依赖矩阵 <a class="header-anchor" href="#分层与依赖矩阵" aria-label="Permalink to &quot;分层与依赖矩阵&quot;">​</a></h2><p>层级越低越基础，只能向下依赖。这套拓扑写在 <code>tooling/eslint-config/src/layers.json</code> 里，由 dependency-cruiser 在 <code>pnpm boundaries</code> 时强制，不靠自觉。</p><table tabindex="0"><thead><tr><th>层</th><th>包</th><th>可依赖</th></tr></thead><tbody><tr><td>1</td><td><code>kernel</code></td><td><code>motion</code></td></tr><tr><td>1</td><td><code>machine</code></td><td><code>kernel</code></td></tr><tr><td>1</td><td><code>motion</code></td><td>—</td></tr><tr><td>1</td><td><code>tokens</code></td><td>—</td></tr><tr><td>1</td><td><code>icons</code></td><td>—</td></tr><tr><td>1</td><td><code>pointer</code></td><td>—</td></tr><tr><td>2</td><td><code>behavior</code></td><td><code>kernel</code> <code>machine</code> <code>motion</code></td></tr><tr><td>2</td><td><code>position</code></td><td><code>kernel</code></td></tr><tr><td>2</td><td><code>code-highlight</code></td><td><code>kernel</code></td></tr><tr><td>2</td><td><code>chat-stream</code></td><td><code>kernel</code></td></tr><tr><td>2</td><td><code>markdown</code></td><td><code>kernel</code></td></tr><tr><td>2</td><td><code>sound</code></td><td><code>kernel</code></td></tr><tr><td>2</td><td><code>animations</code></td><td><code>kernel</code> <code>motion</code></td></tr><tr><td>3</td><td><code>headless</code></td><td><code>kernel</code> <code>machine</code> <code>behavior</code> <code>tokens</code> <code>motion</code> <code>pointer</code></td></tr><tr><td>3</td><td><code>styles</code></td><td>—（纯 CSS，不得依赖任何 JS 包）</td></tr><tr><td>3</td><td><code>backgrounds</code></td><td><code>kernel</code> <code>behavior</code> <code>motion</code></td></tr><tr><td>4</td><td><code>vue</code></td><td><code>kernel</code> <code>machine</code> <code>behavior</code> <code>headless</code> <code>position</code> <code>code-highlight</code> <code>tokens</code> <code>backgrounds</code> <code>sound</code> <code>motion</code> <code>pointer</code></td></tr><tr><td>4</td><td><code>web-components</code></td><td><code>kernel</code> <code>machine</code> <code>behavior</code> <code>headless</code> <code>position</code> <code>code-highlight</code> <code>tokens</code> <code>backgrounds</code> <code>motion</code> <code>pointer</code></td></tr></tbody></table><p>除分层外还有三条硬规则，同样由门禁执行：</p><ul><li><strong>库包的运行时代码不得引第三方。</strong> 唯一登记在案的例外是 <code>@internationalized/date</code>，只有 <code>headless</code> 的日期族在用。</li><li><strong><code>styles</code> 是纯 CSS。</strong> 它不依赖任何 JS 包，因此可以脱离整个 JS 层单独使用。</li><li><strong>依赖版本只从 workspace catalog 取。</strong> 包内一律写 <code>catalog:</code> 或 <code>workspace:</code> 协议引用，不得内联版本号。</li></ul><h2 id="一次交互经过哪些层" tabindex="-1">一次交互经过哪些层 <a class="header-anchor" href="#一次交互经过哪些层" aria-label="Permalink to &quot;一次交互经过哪些层&quot;">​</a></h2><p>以「点击对话框的触发器」为例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户点击</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>适配器把 DOM 事件交给 connect 产出的 onClick        （vue / web-components）</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>service.send({ type: &#39;TRIGGER.CLICK&#39; })            （machine）</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>状态机转移 closed → open，执行 entry 动作           （machine）</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├─► 行为原语接管：锁滚动、建焦点域、压入层栈      （behavior）</span></span>
<span class="line"><span>   ├─► 浮层族还会请定位引擎算坐标                    （position）</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>适配器重新读 connect，把新的 aria-* / data-* 铺到部件上</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>皮肤按 [data-state=&#39;open&#39;] 命中新规则，动画播放      （styles）</span></span></code></pre></div><p>关键在于中间那三步与框架无关。Vue 适配器和 Web Components 适配器各自只负责最外两步。</p><h2 id="包一览" tabindex="-1">包一览 <a class="header-anchor" href="#包一览" aria-label="Permalink to &quot;包一览&quot;">​</a></h2><p>按职责分四组。详细依赖关系见<a href="./npm-package-dependency">包与依赖关系</a>。</p><p><strong>内核与原语</strong></p><table tabindex="0"><thead><tr><th>包</th><th>职责</th></tr></thead><tbody><tr><td><code>@xihan-ui/kernel</code></td><td>结构原语：解剖、<code>mergeProps</code>、<code>normalizeProps</code>、Scope、层栈、诊断通道</td></tr><tr><td><code>@xihan-ui/machine</code></td><td>薄状态机运行时：<code>createMachine</code>、解释器契约、受控值绑定</td></tr><tr><td><code>@xihan-ui/behavior</code></td><td>交互行为原语：消隐层、焦点域、滚动锁、进出场、集合导航、typeahead</td></tr><tr><td><code>@xihan-ui/motion</code></td><td>动效原语：缓动单一真源、纯补间、帧循环、减弱动效偏好、解析解弹簧</td></tr><tr><td><code>@xihan-ui/position</code></td><td>浮层定位引擎，自研，零第三方依赖</td></tr><tr><td><code>@xihan-ui/pointer</code></td><td>指针会话：一根指针从按下到抬起的跟手、过滤与收尾，自研，零依赖</td></tr></tbody></table><p><strong>组件与适配器</strong></p><table tabindex="0"><thead><tr><th>包</th><th>职责</th></tr></thead><tbody><tr><td><code>@xihan-ui/headless</code></td><td>121 个组件的解剖 + 状态机 + <code>connect</code>，无样式、无框架</td></tr><tr><td><code>@xihan-ui/vue</code></td><td>Vue 3 适配器</td></tr><tr><td><code>@xihan-ui/web-components</code></td><td>Web Components 适配器，自研响应式基类</td></tr></tbody></table><p><strong>表现</strong></p><table tabindex="0"><thead><tr><th>包</th><th>职责</th></tr></thead><tbody><tr><td><code>@xihan-ui/tokens</code></td><td>设计令牌（DTCG 源）与主题运行时（明暗 / 品牌 / 密度 / 对比度 / 书写方向）</td></tr><tr><td><code>@xihan-ui/styles</code></td><td>默认皮肤，按 <code>@layer</code> 分层的纯 CSS</td></tr><tr><td><code>@xihan-ui/icons</code></td><td>图标集</td></tr></tbody></table><p><strong>内容与效果</strong></p><table tabindex="0"><thead><tr><th>包</th><th>职责</th></tr></thead><tbody><tr><td><code>@xihan-ui/chat-stream</code></td><td>AI 协议内核：SSE 读取 → 协议归一 → parts 归约 → 会话 store</td></tr><tr><td><code>@xihan-ui/markdown</code></td><td>流式 Markdown 渲染内核，增量切块 + 稳定 key</td></tr><tr><td><code>@xihan-ui/code-highlight</code></td><td>代码着色，自研粗粒度词法器</td></tr><tr><td><code>@xihan-ui/backgrounds</code></td><td>WebGL2 背景效果与数据驱动粒子点云</td></tr><tr><td><code>@xihan-ui/sound</code></td><td>纯 Web Audio 程序化 UI 音效，零音频文件</td></tr><tr><td><code>@xihan-ui/animations</code></td><td>现成的进场与注意动效、错开起播、文字拆分</td></tr></tbody></table><p><code>tooling/*</code> 下还有构建、lint、tsconfig、测试与门禁脚本等内部包，一律不发布。</p><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>XiHan.UI/</span></span>
<span class="line"><span>├── ui/                      # 组件库工作区（pnpm workspace）</span></span>
<span class="line"><span>│   ├── packages/            # 对外发布的库包，按角色分四组</span></span>
<span class="line"><span>│   │   ├── adapters/        # vue · web-components——你选一个</span></span>
<span class="line"><span>│   │   ├── design/          # tokens · styles · icons——外观</span></span>
<span class="line"><span>│   │   ├── features/        # markdown · chat-stream · backgrounds · sound · animations——按需自选</span></span>
<span class="line"><span>│   │   └── engine/          # kernel · machine · motion · pointer · behavior · position · code-highlight · headless</span></span>
<span class="line"><span>│   └── tooling/             # 内部构建与质量工具</span></span>
<span class="line"><span>│       ├── build/           # 打包配置与 exports 回写</span></span>
<span class="line"><span>│       ├── eslint-config/   # lint 规则 + 分层拓扑事实源</span></span>
<span class="line"><span>│       ├── stylelint-config/</span></span>
<span class="line"><span>│       ├── testing/         # 一致性 / 无障碍 / 定位三套判据的运行时</span></span>
<span class="line"><span>│       └── scripts/         # 门禁脚本</span></span>
<span class="line"><span>└── docs/                    # 文档站（VitePress），按 link: 指回上面的库包</span></span></code></pre></div><p>文档站每个组件页的示例渲染的是真实组件，且 Vue 与自定义元素两套写法并排，是对照两套适配器行为的主要手段；示例源文件在 <code>docs/.vitepress/demos/&lt;组件&gt;/</code> 下。</p><h2 id="技术选型" tabindex="-1">技术选型 <a class="header-anchor" href="#技术选型" aria-label="Permalink to &quot;技术选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>选型</th></tr></thead><tbody><tr><td>语言</td><td>TypeScript，ESM only（不提供 CJS）</td></tr><tr><td>运行时要求（消费端）</td><td>Node ≥ 18；浏览器为 2024 年常青版（皮肤用了 <code>@layer</code>、<code>color-mix</code>、<code>oklch</code>）</td></tr><tr><td>运行时要求（开发本仓）</td><td>Node ≥ 24、pnpm ≥ 11</td></tr><tr><td>构建</td><td>tsdown（库包）+ turbo（任务编排）</td></tr><tr><td>样式</td><td>原生 CSS，<code>@layer</code> 分层，<code>oklch</code> 色彩空间，无预处理器</td></tr><tr><td>测试</td><td>vitest（jsdom）+ Playwright（真实 Chromium）</td></tr><tr><td>发布</td><td>changesets，全部库包同属一个 fixed 版本组</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./installation">安装与接入</a>：先把它跑起来</li><li><a href="./quickstart">快速上手</a>：三种用法各写一遍</li><li><a href="./guide/anatomy">解剖与部件契约</a>：理解 <code>data-scope</code> / <code>data-part</code> 这套约定</li></ul>`,33)])])}const u=d(n,[["render",s]]);export{b as __pageData,u as default};
